//! Per-user managed library orchestration; canonical document replacement stays
//! in document::Flow. No GUI file probing/decoding or native/device calls.
use super::*;
use crate::views::collection_library::{Action,Draft,Token};
use skylive_host::collection_library::{self as library,View,Root,RemovePlan};
use skylive_host::storage::SavedFileStamp;
struct Sync{root:Root,path:PathBuf,name:String,stamp:SavedFileStamp}
struct Removal{plan:RemovePlan,session:u64,revision:u64,active:PathBuf}
#[derive(Clone,Copy)]enum Kind{List{open:Option<bool>},Sync,Remove}
struct Pending{request:u64,session:u64,revision:u64,kind:Kind}
#[derive(Default)]pub(super) struct Flow{pub(super) view:Option<Arc<View>>,pub(super) draft:Option<Draft>,next:u64,pending:Option<Pending>,sync:Option<Sync>,remove:Option<Removal>,close_after:bool,problem:Option<String>}
impl Flow{pub(super) fn modal_open(&self)->bool{self.draft.is_some()}pub(super) fn removal_pending(&self)->bool{self.remove.is_some()||self.pending.as_ref().is_some_and(|pending|matches!(pending.kind,Kind::Remove))}}
impl StudioApp{
 fn library_problem(&mut self,error:impl ToString){let error=error.to_string();eprintln!("Managed collection library: {error}");self.collections.problem=Some(error.chars().take(4096).collect());self.message(true,error);}
 pub(super) fn library_created_not_published(&mut self,path:PathBuf){let detail=format!("Managed native collection retained at {}; current document was not replaced: {}",path.display(),self.status);self.library_problem(detail);}
 pub(super) fn library_view(&mut self,view:View){self.collections.view=Some(Arc::new(view));self.collections.problem=None;}
 fn library_root(&self)->Result<Root,String>{Root::for_preferences(self.preferences_path.as_deref().ok_or("Installed settings are not available; finish startup before using managed collections.")?).map_err(|error|error.to_string())}
 fn library_outputs_idle(&mut self)->bool{if self.recording.active()||self.streaming.active()||self.replay.active()||self.ndi_output.owner.any_active()||self.virtual_camera.owned(){self.message(true,"Stop active outputs before changing managed collections.");false}else{true}}
 fn library_list(&mut self,open:Option<bool>,ctx:&egui::Context){if self.io.busy()||self.documents.modal_open(){self.message(true,"Finish the current document operation before refreshing collections.");return;}let root=match self.library_root(){Ok(root)=>root,Err(error)=>{self.library_problem(error);return;}};match self.io.submit(self.session.identity(),Job::LibraryList(root)){Ok(())=>{if let Some(request)=self.io.request(){self.collections.pending=Some(Pending{request,session:self.session.identity(),revision:self.session.snapshot().revision(),kind:Kind::List{open}});}},Err(error)=>self.library_problem(error)}ctx.request_repaint();}
 fn library_create_draft(&mut self,duplicate:bool){if !self.library_outputs_idle(){return;}let Some(view)=&self.collections.view else{return;};if !view.writable{self.message(true,"Managed collection writes are available only on Windows.");return;}let Some(next)=self.collections.next.checked_add(1)else{self.message(true,"Collection draft identity exhausted.");return;};self.collections.next=next;let mut name=if duplicate{self.session.snapshot().name().to_owned()}else{"Untitled".into()};if duplicate{while name.len()>251{name.pop();}name.push_str(" Copy");}self.collections.draft=Some(Draft{token:Token{session:self.session.identity(),revision:self.session.snapshot().revision(),serial:next},name,duplicate,removing:false,source_path:None,error:None});self.invalidate_shortcut_callbacks();}
 pub(super) fn library_action(&mut self,action:Action,ctx:&egui::Context){if matches!(&action,Action::Refresh{..}|Action::Create{..}|Action::Switch{..}|Action::Remove)&&(self.dialog.is_some()||self.setup.is_open()||self.documents.modal_open()||self.close_dialog){self.message(true,"Finish or cancel the current dialog before managing collections.");return;}match action{
  Action::Cancel(token)=>{if self.collections.draft.as_ref().is_some_and(|draft|draft.token==token){self.collections.draft=None;}},
  Action::Refresh{session}=>{if session==self.session.identity(){self.library_list(None,ctx);}},
  Action::Create{duplicate}=>{if !self.library_outputs_idle(){return;}if self.collections.view.is_none(){self.library_list(Some(duplicate),ctx);}else{self.library_create_draft(duplicate);}},
  Action::Switch{session,revision,id}=>{if session!=self.session.identity()||revision!=self.session.snapshot().revision(){self.message(true,"The collection menu changed. Reopen it.");return;}if !self.library_outputs_idle(){return;}let Some(view)=self.collections.view.as_ref().map(|view|(**view).clone())else{self.library_list(None,ctx);return;};if view.path_for(id).as_ref()==self.active_document_path.as_ref(){return;}self.request_library_open(view,id,ctx);},
  Action::Remove=>{if !self.library_outputs_idle(){return;}let Some(view)=&self.collections.view else{self.library_list(None,ctx);return;};let Some(active)=self.active_document_path.as_ref()else{self.message(true,"External or unsaved collections cannot be removed from the managed library.");return;};let Some(entry)=view.entries.iter().find(|entry|view.path_for(entry.id).as_ref()==Some(active))else{self.message(true,"External or unsaved collections cannot be removed from the managed library.");return;};if view.entries.len()<2||!view.writable{self.message(true,"The last managed collection cannot be removed; managed writes require Windows.");return;}let Some(next)=self.collections.next.checked_add(1)else{self.message(true,"Collection draft identity exhausted.");return;};self.collections.next=next;self.collections.draft=Some(Draft{token:Token{session:self.session.identity(),revision:self.session.snapshot().revision(),serial:next},name:entry.name.clone(),duplicate:false,removing:true,source_path:Some(active.clone()),error:None});},
  Action::Confirm{token,name}=>{if !self.collections.draft.as_ref().is_some_and(|draft|draft.token==token&&draft.name==name)||token.session!=self.session.identity()||token.revision!=self.session.snapshot().revision(){self.message(true,"The collection draft is obsolete. Cancel and reopen it.");return;}if !self.library_outputs_idle(){return;}let Some(view)=self.collections.view.as_ref().map(|view|(**view).clone())else{return;};if self.collections.draft.as_ref().is_some_and(|draft|draft.removing){let path=self.collections.draft.take().and_then(|draft|draft.source_path);if let Some(path)=path{self.request_library_remove(view,path,ctx);}}else{let duplicate=self.collections.draft.as_ref().is_some_and(|draft|draft.duplicate);match library::CreatePlan::new(&self.session,&view,name,duplicate,self.active_document_path.as_deref()){Ok(plan)=>{self.collections.draft=None;self.request_library_create(plan,ctx);},Err(error)=>{if let Some(draft)=&mut self.collections.draft{draft.error=Some(error.to_string());}}}}}
 }self.invalidate_shortcut_callbacks();ctx.request_repaint();}
 pub(super) fn library_completion(&mut self,completion:crate::io::Completion,ctx:&egui::Context)->Option<crate::io::Completion>{if !self.collections.pending.as_ref().is_some_and(|pending|pending.request==completion.request){return Some(completion);}let pending=self.collections.pending.take()?;let failed=completion.result.is_err();match(pending.kind,completion.result){(Kind::List{open},Ok(Reply::LibraryListed(view)))=>{self.library_view(view);if let Some(duplicate)=open{if pending.session==self.session.identity()&&pending.revision==self.session.snapshot().revision()&&!self.close_dialog&&!self.allow_close{self.library_create_draft(duplicate);}}},(Kind::Sync,Ok(Reply::LibraryNameSynced(view)))=>{if let Some(view)=view{self.library_view(view);}},(Kind::Remove,Ok(Reply::LibraryRemoved(removed)))=>{self.library_view(removed.view);if let Some(error)=removed.cleanup_problem{self.library_problem(error);}else{self.message(false,crate::status::Status::formatted("Collection removed from the library; recovery file: {path}",&[("{path}",removed.recovery.display().to_string())]));}},(_,Err(error))=>self.library_problem(error),_=>self.library_problem("Collection library returned an unexpected receipt.")}if self.collections.close_after{self.collections.close_after=false;if failed{self.close_dialog=true;}else{self.shutdown(ctx);}}ctx.request_repaint();None}
 pub(super) fn library_saved(&mut self,path:PathBuf,stamp:SavedFileStamp){self.refresh_library_removal_stamp(&path,stamp);let Ok(root)=self.library_root()else{return;};self.collections.sync=Some(Sync{root,path,name:self.session.snapshot().name().to_owned(),stamp});}
 pub(super) fn library_remove_after_publication(&mut self,plan:RemovePlan){let Some(active)=self.active_document_path.clone()else{self.library_problem("Managed removal has no accepted replacement file.");return;};self.collections.remove=Some(Removal{plan,session:self.session.identity(),revision:self.session.snapshot().revision(),active});}
 pub(super) fn flush_library(&mut self,ctx:&egui::Context){if self.io.busy()||self.collections.pending.is_some()||self.documents.modal_open(){return;}let(session,revision,kind,job)=if let Some(removal)=self.collections.remove.take(){if removal.session!=self.session.identity()||removal.revision!=self.session.snapshot().revision()||self.active_document_path.as_ref()!=Some(&removal.active){self.library_problem("The replacement collection changed; the old managed file was not removed.");return;}(removal.session,removal.revision,Kind::Remove,Job::LibraryRemove{plan:removal.plan,active:removal.active})}else if let Some(sync)=self.collections.sync.take(){(self.session.identity(),self.session.snapshot().revision(),Kind::Sync,Job::LibrarySyncName{root:sync.root,path:sync.path,name:sync.name,stamp:sync.stamp})}else{return;};match self.io.submit(session,job){Ok(())=>{if let Some(request)=self.io.request(){self.collections.pending=Some(Pending{request,session,revision,kind});}},Err(error)=>self.library_problem(error)}ctx.request_repaint();}
 pub(super) fn refresh_library_after_publication(&mut self,ctx:&egui::Context){if self.preferences_path.is_some()&&self.collections.view.is_none()&&self.collections.pending.is_none()&&!self.io.busy()&&!self.close_dialog&&!self.documents.modal_open(){self.library_list(None,ctx);}}
 pub(super) fn install_library(&self,ctx:&egui::Context){crate::views::collection_library::install(ctx,&self.session,self.collections.view.clone(),self.active_document_path.clone(),self.collections.problem.clone());}
 pub(super) fn show_library(&mut self,ctx:&egui::Context){if let Some(draft)=&mut self.collections.draft{if let Some(action)=crate::views::collection_library::show(ctx,draft,&self.session,self.io.busy()){self.intent(Intent::CollectionLibrary(action),ctx);}}}
 pub(super) fn cancel_library_draft(&mut self){self.collections.draft=None;if let Some(pending)=&mut self.collections.pending{if matches!(pending.kind,Kind::List{..}){pending.kind=Kind::List{open:None};}}}
 pub(super) fn wait_library_close(&mut self,ctx:&egui::Context)->bool{if self.collections.remove.is_none()&&self.collections.sync.is_none()&&self.collections.pending.is_none(){return false;}self.collections.close_after=true;self.flush_library(ctx);if !self.io.busy(){self.collections.close_after=false;if self.collections.problem.is_some(){self.close_dialog=true;return true;}return false;}ctx.request_repaint_after(std::time::Duration::from_millis(32));true}
 pub(super) fn cancel_library_close(&mut self){self.collections.close_after=false;}
}
